using System.Globalization;
using System.Security.Cryptography;
using System.Text;

namespace PlatinumPrivateLauncher;

internal sealed class ControlBindings
{
    internal sealed record Action(string Label,string Key,int Default,int? Joy);
    internal static readonly Action[] Actions=[new("Move up","Up",1073741906,65537),new("Move down","Down",1073741905,65540),new("Move left","Left",1073741904,65544),new("Move right","Right",1073741903,65538),new("A · Confirm / interact","A",122,0),new("B · Back / run","B",120,1),new("X · Menu","X",99,2),new("Y · Registered item","Y",118,3),new("L shoulder","L",113,9),new("R shoulder","R",101,10),new("Start","Start",13,6),new("Select","Select",1073742053,4),new("Configuration overlay","GUI",9,null)];
    internal readonly Dictionary<string,int> Values=new(StringComparer.OrdinalIgnoreCase);
    internal byte[] Original {get;}
    readonly string text;
    internal ControlBindings(byte[] bytes){Original=(byte[])bytes.Clone();text=new UTF8Encoding(false,true).GetString(bytes).TrimStart('\uFEFF');foreach(var a in Actions){Values[a.Key+"Key"]=a.Default;if(a.Joy is int joy)Values[a.Key+"JoyKey"]=joy;}string section="";foreach(var line in text.Replace("\r\n","\n").Split('\n')){var t=line.Trim();if(t.StartsWith('[')&&t.EndsWith(']'))section=t[1..^1];if(!section.Equals("PAD",StringComparison.OrdinalIgnoreCase))continue;int eq=t.IndexOf('=');if(eq>0&&Values.ContainsKey(t[..eq].Trim())){if(!int.TryParse(t[(eq+1)..].Split(';','#')[0].Trim(),NumberStyles.Integer,CultureInfo.InvariantCulture,out int value))throw new IOException("Invalid control value: "+t[..eq]);Values[t[..eq].Trim()]=value;}}}
    internal byte[] Build(IReadOnlyDictionary<string,int> edits){if(edits.Any(x=>!Values.ContainsKey(x.Key)||x.Value<0))throw new IOException("Unsupported control binding.");var wanted=new Dictionary<string,int>(Values,StringComparer.OrdinalIgnoreCase);foreach(var e in edits)wanted[e.Key]=e.Value;var newline=text.Contains("\r\n")?"\r\n":"\n";var output=new List<string>();var written=new HashSet<string>(StringComparer.OrdinalIgnoreCase);string section="";bool found=false;
        void Missing(){foreach(var e in wanted)if(written.Add(e.Key))output.Add(e.Key+"="+e.Value.ToString(CultureInfo.InvariantCulture));}
        foreach(var line in text.Replace("\r\n","\n").Split('\n')){var t=line.Trim();if(t.StartsWith('[')&&t.EndsWith(']')){if(section.Equals("PAD",StringComparison.OrdinalIgnoreCase))Missing();section=t[1..^1];if(section.Equals("PAD",StringComparison.OrdinalIgnoreCase))found=true;}int eq=t.IndexOf('=');if(section.Equals("PAD",StringComparison.OrdinalIgnoreCase)&&eq>0&&wanted.TryGetValue(t[..eq].Trim(),out int value)){var key=t[..eq].Trim();output.Add(key+"="+value.ToString(CultureInfo.InvariantCulture));written.Add(key);}else output.Add(line);}
        if(section.Equals("PAD",StringComparison.OrdinalIgnoreCase))Missing();if(!found){output.Add("[PAD]");Missing();}return new UTF8Encoding(false).GetBytes(string.Join(newline,output));}
    internal static int FromWindowsKey(Keys key){key&=Keys.KeyCode;if(key is >=Keys.A and <=Keys.Z)return 'a'+(int)key-(int)Keys.A;if(key is >=Keys.D0 and <=Keys.D9)return '0'+(int)key-(int)Keys.D0;if(key is >=Keys.F1 and <=Keys.F12)return 1073741882+(int)key-(int)Keys.F1;if(key is >=Keys.NumPad1 and <=Keys.NumPad9)return 1073741913+(int)key-(int)Keys.NumPad1;return key switch{Keys.Up=>1073741906,Keys.Down=>1073741905,Keys.Left=>1073741904,Keys.Right=>1073741903,Keys.Return=>13,Keys.Space=>32,Keys.Tab=>9,Keys.Escape=>27,Keys.Back=>8,Keys.Delete=>127,Keys.Insert=>1073741897,Keys.Home=>1073741898,Keys.End=>1073741901,Keys.PageUp=>1073741899,Keys.PageDown=>1073741902,Keys.ShiftKey or Keys.LShiftKey=>1073742049,Keys.RShiftKey=>1073742053,Keys.ControlKey or Keys.LControlKey=>1073742048,Keys.RControlKey=>1073742052,Keys.Menu or Keys.LMenu=>1073742050,Keys.RMenu=>1073742054,Keys.Oemcomma=>44,Keys.OemPeriod=>46,Keys.OemQuestion=>47,Keys.OemSemicolon=>59,Keys.OemQuotes=>39,Keys.OemOpenBrackets=>91,Keys.OemCloseBrackets=>93,Keys.OemPipe=>92,Keys.OemMinus=>45,Keys.Oemplus=>61,Keys.Oemtilde=>96,Keys.NumPad0=>1073741922,Keys.Decimal=>1073741923,_=>throw new IOException("Choose a letter, number, arrow, function key or common keyboard key.")};}
    internal static void SelfTest(){var bytes=Encoding.UTF8.GetBytes("[General]\r\nMacAddr=keep-me\r\n[PAD]\r\nAKey=122\r\nJoyAxisDeadzone=8191\r\n[OSNVRAM]\r\nOwner_Nickname=KeepThis\r\n");var doc=new ControlBindings(bytes);var changed=doc.Build(new Dictionary<string,int>{{"AKey",FromWindowsKey(Keys.K)},{"UpJoyKey",65537}});var read=new ControlBindings(changed);if(read.Values["AKey"]!=107||read.Values["UpJoyKey"]!=65537||!Encoding.UTF8.GetString(changed).Contains("MacAddr=keep-me\r\n")||!Encoding.UTF8.GetString(changed).Contains("Owner_Nickname=KeepThis")||!Encoding.UTF8.GetString(changed).Contains("JoyAxisDeadzone=8191")||!doc.Original.SequenceEqual(bytes))throw new Exception("Control settings preservation failed.");if(FromWindowsKey(Keys.Up)!=1073741906||FromWindowsKey(Keys.F12)!=1073741893)throw new Exception("SDL key conversion failed.");}
}
